SELECT
  'trips.LTS2_zone_day_agg.trip_count at ' || COALESCE(CAST(COALESCE(s.trips_to_date__day, d.trips_to_date__day) AS STRING), '') || '|' || COALESCE(
    CAST(COALESCE(s.trips_to_pickup_zone__zone, d.trips_to_pickup_zone__zone) AS STRING),
    ''
  ) AS binding,
  CAST(s.trip_count AS STRING) AS source_value,
  CAST(d.trip_count AS STRING) AS detail_value
FROM s1_source AS s
LEFT JOIN s1_detail AS d
  ON s.trips_to_date__day IS NOT DISTINCT FROM d.trips_to_date__day
  AND s.trips_to_pickup_zone__zone IS NOT DISTINCT FROM d.trips_to_pickup_zone__zone
WHERE
  COALESCE(s.trip_count, 0) IS DISTINCT FROM COALESCE(d.trip_count, 0)

union all

SELECT
  'trips.LTS2_zone_day_agg.trip_count at ' || COALESCE(CAST(COALESCE(s.trips_to_date__day, d.trips_to_date__day) AS STRING), '') || '|' || COALESCE(
    CAST(COALESCE(s.trips_to_pickup_zone__zone, d.trips_to_pickup_zone__zone) AS STRING),
    ''
  ) AS binding,
  CAST(s.trip_count AS STRING) AS source_value,
  CAST(d.trip_count AS STRING) AS detail_value
FROM s1_detail AS d
LEFT JOIN (
  SELECT
    1 AS matched_source,
    *
  FROM s1_source
) AS s
  ON s.trips_to_date__day IS NOT DISTINCT FROM d.trips_to_date__day
  AND s.trips_to_pickup_zone__zone IS NOT DISTINCT FROM d.trips_to_pickup_zone__zone
WHERE
  COALESCE(s.trip_count, 0) IS DISTINCT FROM COALESCE(d.trip_count, 0)
  AND s.matched_source IS NULL

union all

