  'shift.LTS7_driver_scorecard.fleet_on_trip_hours at ' || COALESCE(CAST(COALESCE(s.shift_to_driver__row, d.shift_to_driver__row) AS STRING), '') AS binding,
  CAST(s.fleet_on_trip_hours AS STRING) AS source_value,
  CAST(d.fleet_on_trip_hours AS STRING) AS detail_value
FROM s13_source AS s
LEFT JOIN s13_detail AS d
  ON s.shift_to_driver__row IS NOT DISTINCT FROM d.shift_to_driver__row
WHERE
